1	import { and, eq } from "drizzle-orm";
2	import { Router, type Request, type Response } from "express";
3	import type { Db } from "@paperclipai/db";
4	import { issues, projects, projectWorkspaces } from "@paperclipai/db";
5	import {
6	  findWorkspaceCommandDefinition,
7	  matchWorkspaceRuntimeServiceToCommand,
8	  updateExecutionWorkspaceSchema,
9	  workspaceRuntimeControlTargetSchema,
10	} from "@paperclipai/shared";
11	import type { WorkspaceRuntimeDesiredState, WorkspaceRuntimeServiceStateMap } from "@paperclipai/shared";
12	import { validate } from "../middleware/validate.js";
13	import { executionWorkspaceService, logActivity, workspaceOperationService } from "../services/index.js";
14	import { mergeExecutionWorkspaceConfig, readExecutionWorkspaceConfig } from "../services/execution-workspaces.js";
15	import { parseProjectExecutionWorkspacePolicy } from "../services/execution-workspace-policy.js";
16	import { readProjectWorkspaceRuntimeConfig } from "../services/project-workspace-runtime-config.js";
17	import {
18	  buildWorkspaceRuntimeDesiredStatePatch,
19	  cleanupExecutionWorkspaceArtifacts,
20	  ensurePersistedExecutionWorkspaceAvailable,
21	  listConfiguredRuntimeServiceEntries,
22	  runWorkspaceJobForControl,
23	  startRuntimeServicesForWorkspaceControl,
24	  stopRuntimeServicesForExecutionWorkspace,
25	} from "../services/workspace-runtime.js";
26	import { assertCompanyAccess, getActorInfo } from "./authz.js";
27	import {
28	  assertNoAgentHostWorkspaceCommandMutation,
29	  collectExecutionWorkspaceCommandPaths,
30	} from "./workspace-command-authz.js";
31	import { assertCanManageExecutionWorkspaceRuntimeServices } from "./workspace-runtime-service-authz.js";
32	import { appendWithCap } from "../adapters/utils.js";
33	
34	const WORKSPACE_CONTROL_OUTPUT_MAX_CHARS = 256 * 1024;
35	
36	export function executionWorkspaceRoutes(db: Db) {
37	  const router = Router();
38	  const svc = executionWorkspaceService(db);
39	  const workspaceOperationsSvc = workspaceOperationService(db);
40	
41	  router.get("/companies/:companyId/execution-workspaces", async (req, res) => {
42	    const companyId = req.params.companyId as string;
43	    assertCompanyAccess(req, companyId);
44	    const filters = {
45	      projectId: req.query.projectId as string | undefined,
46	      projectWorkspaceId: req.query.projectWorkspaceId as string | undefined,
47	      issueId: req.query.issueId as string | undefined,
48	      status: req.query.status as string | undefined,
49	      reuseEligible: req.query.reuseEligible === "true",
50	    };
51	    const workspaces = req.query.summary === "true"
52	      ? await svc.listSummaries(companyId, filters)
53	      : await svc.list(companyId, filters);
54	    res.json(workspaces);
55	  });
56	
57	  router.get("/execution-workspaces/:id", async (req, res) => {
58	    const id = req.params.id as string;
59	    const workspace = await svc.getById(id);
60	    if (!workspace) {
61	      res.status(404).json({ error: "Execution workspace not found" });
62	      return;
63	    }
64	    assertCompanyAccess(req, workspace.companyId);
65	    res.json(workspace);
66	  });
67	
68	  router.get("/execution-workspaces/:id/close-readiness", async (req, res) => {
69	    const id = req.params.id as string;
70	    const workspace = await svc.getById(id);
71	    if (!workspace) {
72	      res.status(404).json({ error: "Execution workspace not found" });
73	      return;
74	    }
75	    assertCompanyAccess(req, workspace.companyId);
76	    const readiness = await svc.getCloseReadiness(id);
77	    if (!readiness) {
78	      res.status(404).json({ error: "Execution workspace not found" });
79	      return;
80	    }
81	    res.json(readiness);
82	  });
83	
84	  router.get("/execution-workspaces/:id/workspace-operations", async (req, res) => {
85	    const id = req.params.id as string;
86	    const workspace = await svc.getById(id);
87	    if (!workspace) {
88	      res.status(404).json({ error: "Execution workspace not found" });
89	      return;
90	    }
91	    assertCompanyAccess(req, workspace.companyId);
92	    const operations = await workspaceOperationsSvc.listForExecutionWorkspace(id);
93	    res.json(operations);
94	  });
95	
96	  async function handleExecutionWorkspaceRuntimeCommand(req: Request, res: Response) {
97	    const id = req.params.id as string;
98	    const action = String(req.params.action ?? "").trim().toLowerCase();
99	    if (action !== "start" && action !== "stop" && action !== "restart" && action !== "run") {
100	      res.status(404).json({ error: "Workspace command action not found" });
101	      return;
102	    }
103	
104	    const existing = await svc.getById(id);
105	    if (!existing) {
106	      res.status(404).json({ error: "Execution workspace not found" });
107	      return;
108	    }
109	    assertCompanyAccess(req, existing.companyId);
110	
111	    await assertCanManageExecutionWorkspaceRuntimeServices(db, req, {
112	      companyId: existing.companyId,
113	      executionWorkspaceId: existing.id,
114	      sourceIssueId: existing.sourceIssueId,
115	    });
116	
117	    const workspaceCwd = existing.cwd;
118	    if (!workspaceCwd) {
119	      res.status(422).json({ error: "Execution workspace needs a local path before Paperclip can run workspace commands" });
120	      return;
121	    }
122	
123	    const projectWorkspace = existing.projectWorkspaceId
124	      ? await db
125	          .select({
126	            id: projectWorkspaces.id,
127	            cwd: projectWorkspaces.cwd,
128	            repoUrl: projectWorkspaces.repoUrl,
129	            repoRef: projectWorkspaces.repoRef,
130	            defaultRef: projectWorkspaces.defaultRef,
131	            metadata: projectWorkspaces.metadata,
132	          })
133	          .from(projectWorkspaces)
134	          .where(
135	            and(
136	              eq(projectWorkspaces.id, existing.projectWorkspaceId),
137	              eq(projectWorkspaces.companyId, existing.companyId),
138	            ),
139	          )
140	          .then((rows) => rows[0] ?? null)
141	      : null;
142	    const projectWorkspaceRuntime = readProjectWorkspaceRuntimeConfig(
143	      (projectWorkspace?.metadata as Record<string, unknown> | null) ?? null,
144	    )?.workspaceRuntime ?? null;
145	    const projectPolicy = existing.projectId
146	      ? await db
147	          .select({
148	            executionWorkspacePolicy: projects.executionWorkspacePolicy,
149	          })
150	          .from(projects)
151	          .where(
152	            and(
153	              eq(projects.id, existing.projectId),
154	              eq(projects.companyId, existing.companyId),
155	            ),
156	          )
157	          .then((rows) => parseProjectExecutionWorkspacePolicy(rows[0]?.executionWorkspacePolicy))
158	      : null;
159	    const effectiveRuntimeConfig = existing.config?.workspaceRuntime ?? projectWorkspaceRuntime ?? null;
160	    const target = req.body as { workspaceCommandId?: string | null; runtimeServiceId?: string | null; serviceIndex?: number | null };
161	    const configuredServices = effectiveRuntimeConfig
162	      ? listConfiguredRuntimeServiceEntries({ workspaceRuntime: effectiveRuntimeConfig })
163	      : [];
164	    const workspaceCommand = effectiveRuntimeConfig
165	      ? findWorkspaceCommandDefinition(effectiveRuntimeConfig, target.workspaceCommandId ?? null)
166	      : null;
167	    if (target.workspaceCommandId && !workspaceCommand) {
168	      res.status(404).json({ error: "Workspace command not found for this execution workspace" });
169	      return;
170	    }
171	    if (target.runtimeServiceId && !(existing.runtimeServices ?? []).some((service) => service.id === target.runtimeServiceId)) {
172	      res.status(404).json({ error: "Runtime service not found for this execution workspace" });
173	      return;
174	    }
175	    const matchedRuntimeService =
176	      workspaceCommand?.kind === "service" && !target.runtimeServiceId
177	        ? matchWorkspaceRuntimeServiceToCommand(workspaceCommand, existing.runtimeServices ?? [])
178	        : null;
179	    const selectedRuntimeServiceId = target.runtimeServiceId ?? matchedRuntimeService?.id ?? null;
180	    const selectedServiceIndex =
181	      workspaceCommand?.kind === "service"
182	        ? workspaceCommand.serviceIndex
183	        : target.serviceIndex ?? null;
184	    if (
185	      selectedServiceIndex !== undefined
186	      && selectedServiceIndex !== null
187	      && (selectedServiceIndex < 0 || selectedServiceIndex >= configuredServices.length)
188	    ) {
189	      res.status(422).json({ error: "Selected runtime service is not defined in this execution workspace runtime config" });
190	      return;
191	    }
192	    if (workspaceCommand?.kind === "job" && action !== "run") {
193	      res.status(422).json({ error: `Workspace job "${workspaceCommand.name}" can only be run` });
194	      return;
195	    }
196	    if (workspaceCommand?.kind === "service" && action === "run") {
197	      res.status(422).json({ error: `Workspace service "${workspaceCommand.name}" should be started or restarted, not run` });
198	      return;
199	    }
200	    if (action === "run" && !workspaceCommand) {
201	      res.status(422).json({ error: "Select a workspace job to run" });
202	      return;
203	    }
204	
205	    if ((action === "start" || action === "restart") && !effectiveRuntimeConfig) {
206	      res.status(422).json({ error: "Execution workspace has no workspace command configuration or inherited project workspace default" });
207	      return;
208	    }
209	
210	    const actor = getActorInfo(req);
211	    const recorder = workspaceOperationsSvc.createRecorder({
212	      companyId: existing.companyId,
213	      executionWorkspaceId: existing.id,
214	    });
215	    let runtimeServiceCount = existing.runtimeServices?.length ?? 0;
216	    let stdout = "";
217	    let stderr = "";
218	
219	    const operation = await recorder.recordOperation({
220	      phase: action === "stop" ? "workspace_teardown" : "workspace_provision",
221	      command: workspaceCommand?.command ?? `workspace command ${action}`,
222	      cwd: existing.cwd,
223	      metadata: {
224	        action,
225	        executionWorkspaceId: existing.id,
226	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
227	        workspaceCommandKind: workspaceCommand?.kind ?? null,
228	        workspaceCommandName: workspaceCommand?.name ?? null,
229	        runtimeServiceId: selectedRuntimeServiceId,
230	        serviceIndex: selectedServiceIndex,
231	      },
232	      run: async () => {
233	        const ensureWorkspaceAvailable = async () =>
234	          await ensurePersistedExecutionWorkspaceAvailable({
235	            base: {
236	              baseCwd: projectWorkspace?.cwd ?? workspaceCwd,
237	              source: existing.mode === "shared_workspace" ? "project_primary" : "task_session",
238	              projectId: existing.projectId,
239	              workspaceId: existing.projectWorkspaceId,
240	              repoUrl: existing.repoUrl,
241	              repoRef: existing.baseRef,
242	            },
243	            workspace: {
244	              mode: existing.mode,
245	              strategyType: existing.strategyType,
246	              cwd: existing.cwd,
247	              providerRef: existing.providerRef,
248	              projectId: existing.projectId,
249	              projectWorkspaceId: existing.projectWorkspaceId,
250	              repoUrl: existing.repoUrl,
251	              baseRef: existing.baseRef,
252	              branchName: existing.branchName,
253	              config: {
254	                ...existing.config,
255	                provisionCommand:
256	                  existing.config?.provisionCommand
257	                  ?? projectPolicy?.workspaceStrategy?.provisionCommand
258	                  ?? null,
259	              },
260	            },
261	            issue: existing.sourceIssueId
262	              ? {
263	                  id: existing.sourceIssueId,
264	                  identifier: null,
265	                  title: existing.name,
266	                }
267	              : null,
268	            agent: {
269	              id: actor.agentId ?? null,
270	              name: actor.actorType === "user" ? "Board" : "Agent",
271	              companyId: existing.companyId,
272	            },
273	            recorder,
274	          });
275	
276	        if (action === "run") {
277	          if (!workspaceCommand || workspaceCommand.kind !== "job") {
278	            throw new Error("Workspace job selection is required");
279	          }
280	          const availableWorkspace = await ensureWorkspaceAvailable();
281	          if (!availableWorkspace) {
282	            throw new Error("Execution workspace needs a local path before Paperclip can run workspace commands");
283	          }
284	          return await runWorkspaceJobForControl({
285	            actor: {
286	              id: actor.agentId ?? null,
287	              name: actor.actorType === "user" ? "Board" : "Agent",
288	              companyId: existing.companyId,
289	            },
290	            issue: existing.sourceIssueId
291	              ? {
292	                  id: existing.sourceIssueId,
293	                  identifier: null,
294	                  title: existing.name,
295	                }
296	              : null,
297	            workspace: availableWorkspace,
298	            command: workspaceCommand.rawConfig,
299	            adapterEnv: {},
300	            recorder,
301	            metadata: {
302	              action,
303	              executionWorkspaceId: existing.id,
304	              workspaceCommandId: workspaceCommand.id,
305	            },
306	          }).then((nestedOperation) => ({
307	            status: "succeeded" as const,
308	            exitCode: 0,
309	            metadata: {
310	              nestedOperationId: nestedOperation?.id ?? null,
311	              runtimeServiceCount,
312	            },
313	          }));
314	        }
315	
316	        const onLog = async (stream: "stdout" | "stderr", chunk: string) => {
317	          if (stream === "stdout") stdout = appendWithCap(stdout, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
318	          else stderr = appendWithCap(stderr, chunk, WORKSPACE_CONTROL_OUTPUT_MAX_CHARS);
319	        };
320	
321	        if (action === "stop" || action === "restart") {
322	          await stopRuntimeServicesForExecutionWorkspace({
323	            db,
324	            executionWorkspaceId: existing.id,
325	            workspaceCwd,
326	            runtimeServiceId: selectedRuntimeServiceId,
327	          });
328	        }
329	
330	        if (action === "start" || action === "restart") {
331	          const availableWorkspace = await ensureWorkspaceAvailable();
332	          if (!availableWorkspace) {
333	            throw new Error("Execution workspace needs a local path before Paperclip can manage local runtime services");
334	          }
335	          const startedServices = await startRuntimeServicesForWorkspaceControl({
336	            db,
337	            actor: {
338	              id: actor.agentId ?? null,
339	              name: actor.actorType === "user" ? "Board" : "Agent",
340	              companyId: existing.companyId,
341	            },
342	            issue: existing.sourceIssueId
343	              ? {
344	                  id: existing.sourceIssueId,
345	                  identifier: null,
346	                  title: existing.name,
347	                }
348	              : null,
349	            workspace: availableWorkspace,
350	            executionWorkspaceId: existing.id,
351	            config: { workspaceRuntime: effectiveRuntimeConfig },
352	            adapterEnv: {},
353	            onLog,
354	            serviceIndex: selectedServiceIndex,
355	          });
356	          runtimeServiceCount = startedServices.length;
357	        } else {
358	          runtimeServiceCount = selectedRuntimeServiceId ? Math.max(0, (existing.runtimeServices?.length ?? 1) - 1) : 0;
359	        }
360	
361	        const currentDesiredState: WorkspaceRuntimeDesiredState =
362	          existing.config?.desiredState
363	          ?? ((existing.runtimeServices ?? []).some((service) => service.status === "starting" || service.status === "running")
364	            ? "running"
365	            : "stopped");
366	        const nextRuntimeState: {
367	          desiredState: WorkspaceRuntimeDesiredState;
368	          serviceStates: WorkspaceRuntimeServiceStateMap | null | undefined;
369	        } = selectedRuntimeServiceId && (selectedServiceIndex === undefined || selectedServiceIndex === null)
370	          ? {
371	              desiredState: currentDesiredState,
372	              serviceStates: existing.config?.serviceStates ?? null,
373	            }
374	          : buildWorkspaceRuntimeDesiredStatePatch({
375	              config: { workspaceRuntime: effectiveRuntimeConfig },
376	              currentDesiredState,
377	              currentServiceStates: existing.config?.serviceStates ?? null,
378	              action,
379	              serviceIndex: selectedServiceIndex,
380	            });
381	        const metadata = mergeExecutionWorkspaceConfig(existing.metadata as Record<string, unknown> | null, {
382	          desiredState: nextRuntimeState.desiredState,
383	          serviceStates: nextRuntimeState.serviceStates,
384	        });
385	        await svc.update(existing.id, { metadata });
386	
387	        return {
388	          status: "succeeded",
389	          stdout,
390	          stderr,
391	          system:
392	            action === "stop"
393	              ? "Stopped execution workspace runtime services.\n"
394	              : action === "restart"
395	                ? "Restarted execution workspace runtime services.\n"
396	                : "Started execution workspace runtime services.\n",
397	          metadata: {
398	            runtimeServiceCount,
399	            workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
400	            runtimeServiceId: selectedRuntimeServiceId,
401	            serviceIndex: selectedServiceIndex,
402	          },
403	        };
404	      },
405	    });
406	
407	    const workspace = await svc.getById(id);
408	    if (!workspace) {
409	      res.status(404).json({ error: "Execution workspace not found" });
410	      return;
411	    }
412	
413	    await logActivity(db, {
414	      companyId: existing.companyId,
415	      actorType: actor.actorType,
416	      actorId: actor.actorId,
417	      agentId: actor.agentId,
418	      runId: actor.runId,
419	      action: `execution_workspace.runtime_${action}`,
420	      entityType: "execution_workspace",
421	      entityId: existing.id,
422	      details: {
423	        runtimeServiceCount,
424	        workspaceCommandId: workspaceCommand?.id ?? target.workspaceCommandId ?? null,
425	        workspaceCommandKind: workspaceCommand?.kind ?? null,
426	        workspaceCommandName: workspaceCommand?.name ?? null,
427	        runtimeServiceId: selectedRuntimeServiceId,
428	        serviceIndex: selectedServiceIndex,
429	      },
430	    });
431	
432	    res.json({
433	      workspace,
434	      operation,
435	    });
436	  }
437	
438	  router.post("/execution-workspaces/:id/runtime-services/:action", validate(workspaceRuntimeControlTargetSchema), handleExecutionWorkspaceRuntimeCommand);
439	  router.post("/execution-workspaces/:id/runtime-commands/:action", validate(workspaceRuntimeControlTargetSchema), handleExecutionWorkspaceRuntimeCommand);
440	
441	  router.patch("/execution-workspaces/:id", validate(updateExecutionWorkspaceSchema), async (req, res) => {
442	    const id = req.params.id as string;
443	    const existing = await svc.getById(id);
444	    if (!existing) {
445	      res.status(404).json({ error: "Execution workspace not found" });
446	      return;
447	    }
448	    assertCompanyAccess(req, existing.companyId);
449	    assertNoAgentHostWorkspaceCommandMutation(
450	      req,
451	      collectExecutionWorkspaceCommandPaths({
452	        config: req.body.config,
453	        metadata: req.body.metadata,
454	      }),
455	    );
456	    const patch: Record<string, unknown> = {
457	      ...(req.body.name === undefined ? {} : { name: req.body.name }),
458	      ...(req.body.cwd === undefined ? {} : { cwd: req.body.cwd }),
459	      ...(req.body.repoUrl === undefined ? {} : { repoUrl: req.body.repoUrl }),
460	      ...(req.body.baseRef === undefined ? {} : { baseRef: req.body.baseRef }),
461	      ...(req.body.branchName === undefined ? {} : { branchName: req.body.branchName }),
462	      ...(req.body.providerRef === undefined ? {} : { providerRef: req.body.providerRef }),
463	      ...(req.body.status === undefined ? {} : { status: req.body.status }),
464	      ...(req.body.cleanupReason === undefined ? {} : { cleanupReason: req.body.cleanupReason }),
465	      ...(req.body.cleanupEligibleAt !== undefined
466	        ? { cleanupEligibleAt: req.body.cleanupEligibleAt ? new Date(req.body.cleanupEligibleAt) : null }
467	        : {}),
468	    };
469	    if (req.body.metadata !== undefined || req.body.config !== undefined) {
470	      const requestedMetadata = req.body.metadata === undefined
471	        ? (existing.metadata as Record<string, unknown> | null)
472	        : (req.body.metadata as Record<string, unknown> | null);
473	      patch.metadata = req.body.config === undefined
474	        ? requestedMetadata
475	        : mergeExecutionWorkspaceConfig(requestedMetadata, req.body.config ?? null);
476	    }
477	    let workspace = existing;
478	    let cleanupWarnings: string[] = [];
479	    const configForCleanup = readExecutionWorkspaceConfig(
480	      ((patch.metadata as Record<string, unknown> | null | undefined) ?? (existing.metadata as Record<string, unknown> | null)) ?? null,
481	    );
482	
483	    if (req.body.status === "archived" && existing.status !== "archived") {
484	      const readiness = await svc.getCloseReadiness(existing.id);
485	      if (!readiness) {
486	        res.status(404).json({ error: "Execution workspace not found" });
487	        return;
488	      }
489	
490	      if (readiness.state === "blocked") {
491	        res.status(409).json({
492	          error: readiness.blockingReasons[0] ?? "Execution workspace cannot be closed right now",
493	          closeReadiness: readiness,
494	        });
495	        return;
496	      }
497	
498	      const closedAt = new Date();
499	      const archivedWorkspace = await svc.update(id, {
500	        ...patch,
501	        status: "archived",
502	        closedAt,
503	        cleanupReason: null,
504	      });
505	      if (!archivedWorkspace) {
506	        res.status(404).json({ error: "Execution workspace not found" });
507	        return;
508	      }
509	      workspace = archivedWorkspace;
510	
511	      if (existing.mode === "shared_workspace") {
512	        await db
513	          .update(issues)
514	          .set({
515	            executionWorkspaceId: null,
516	            updatedAt: new Date(),
517	          })
518	          .where(
519	            and(
520	              eq(issues.companyId, existing.companyId),
521	              eq(issues.executionWorkspaceId, existing.id),
522	            ),
523	          );
524	      }
525	
526	      try {
527	        await stopRuntimeServicesForExecutionWorkspace({
528	          db,
529	          executionWorkspaceId: existing.id,
530	          workspaceCwd: existing.cwd,
531	        });
532	        const projectWorkspace = existing.projectWorkspaceId
533	          ? await db
534	              .select({
535	                cwd: projectWorkspaces.cwd,
536	                cleanupCommand: projectWorkspaces.cleanupCommand,
537	              })
538	              .from(projectWorkspaces)
539	            .where(
540	                and(
541	                  eq(projectWorkspaces.id, existing.projectWorkspaceId),
542	                  eq(projectWorkspaces.companyId, existing.companyId),
543	                ),
544	              )
545	              .then((rows) => rows[0] ?? null)
546	          : null;
547	        const projectPolicy = existing.projectId
548	          ? await db
549	              .select({
550	                executionWorkspacePolicy: projects.executionWorkspacePolicy,
551	              })
552	              .from(projects)
553	              .where(and(eq(projects.id, existing.projectId), eq(projects.companyId, existing.companyId)))
554	              .then((rows) => parseProjectExecutionWorkspacePolicy(rows[0]?.executionWorkspacePolicy))
555	          : null;
556	        const cleanupResult = await cleanupExecutionWorkspaceArtifacts({
557	          workspace: existing,
558	          projectWorkspace,
559	          teardownCommand: configForCleanup?.teardownCommand ?? projectPolicy?.workspaceStrategy?.teardownCommand ?? null,
560	          cleanupCommand: configForCleanup?.cleanupCommand ?? null,
561	          recorder: workspaceOperationsSvc.createRecorder({
562	            companyId: existing.companyId,
563	            executionWorkspaceId: existing.id,
564	          }),
565	        });
566	        cleanupWarnings = cleanupResult.warnings;
567	        const cleanupPatch: Record<string, unknown> = {
568	          closedAt,
569	          cleanupReason: cleanupWarnings.length > 0 ? cleanupWarnings.join(" | ") : null,
570	        };
571	        if (!cleanupResult.cleaned) {
572	          cleanupPatch.status = "cleanup_failed";
573	        }
574	        if (cleanupResult.warnings.length > 0 || !cleanupResult.cleaned) {
575	          workspace = (await svc.update(id, cleanupPatch)) ?? workspace;
576	        }
577	      } catch (error) {
578	        const failureReason = error instanceof Error ? error.message : String(error);
579	        workspace =
580	          (await svc.update(id, {
581	            status: "cleanup_failed",
582	            closedAt,
583	            cleanupReason: failureReason,
584	          })) ?? workspace;
585	        res.status(500).json({
586	          error: `Failed to archive execution workspace: ${failureReason}`,
587	        });
588	        return;
589	      }
590	    } else {
591	      const updatedWorkspace = await svc.update(id, patch);
592	      if (!updatedWorkspace) {
593	        res.status(404).json({ error: "Execution workspace not found" });
594	        return;
595	      }
596	      workspace = updatedWorkspace;
597	    }
598	    const actor = getActorInfo(req);
599	    await logActivity(db, {
600	      companyId: existing.companyId,
601	      actorType: actor.actorType,
602	      actorId: actor.actorId,
603	      agentId: actor.agentId,
604	      runId: actor.runId,
605	      action: "execution_workspace.updated",
606	      entityType: "execution_workspace",
607	      entityId: workspace.id,
608	      details: {
609	        changedKeys: Object.keys(req.body).sort(),
610	        ...(cleanupWarnings.length > 0 ? { cleanupWarnings } : {}),
